def esc(v):return html.escape(str(v))
def shell(title,description,body):return '<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(title)+' · Arda Research</title><meta name="description" content="'+esc(description)+'"><meta property="og:type" content="article"><meta property="og:title" content="'+esc(title)+' · Arda Research"><meta property="og:description" content="'+esc(description)+'"><link rel="stylesheet" href="/site-reader.css"></head><body><header><a class="brand" href="/">arda<span> / </span>research</a><nav class="reader-nav"><a href="/">Araştırma masası</a><a href="/#top10">İlk 10</a><a href="/hakkimizda/">Yaklaşımımız</a></nav></header><main>'+body+'<footer><span>ARDA RESEARCH · Yapay zekâ destekli araştırma</span><a href="/hakkimizda/">Yöntem, kaynaklar ve kişisel veriler</a></footer></main></body></html>'
def report(title,value,id):return '<article id="'+id+'" class="card reader-section"><h2>'+title+'</h2><div class="reader-copy">'+esc(value)+'</div></article>'
